templates.partial/site_header:
{# David Universe 3D — HUD + folha de estilo. O header.twig do sistema inclui este partial com only. #}
<style>

:root{
  --du-bg:#121516; --du-bg-2:#0e1011; --du-panel:rgba(24,30,32,.86);
  --du-panel-2:#1d2426; --du-line:rgba(92,198,208,.28); --du-line-soft:rgba(167,179,181,.18);
  --du-cyan:#5cc6d0; --du-cyan-dim:#2b7f89; --du-ink:#dfdfdf; --du-muted:#a7b3b5;
  --du-rose:#eb767e; --du-gold:#ffdf00; --du-green:#7fdc8c;
  --du-radius:4px; --du-radius-lg:8px; --du-max:1180px;
  --du-font:system-ui,-apple-system,"Segoe UI",Roboto,Helvetica,Arial,sans-serif;
  --du-display:"Poiret One","Century Gothic","Trebuchet MS",var(--du-font);
}
*,*::before,*::after{box-sizing:border-box}
.du{font-family:var(--du-font);color:var(--du-ink);line-height:1.70;
  background:var(--du-bg);-webkit-font-smoothing:antialiased}
.du a{color:var(--du-cyan);text-decoration:none}
.du a:hover{text-decoration:underline}
.du h1,.du h2,.du h3,.du h4{font-family:var(--du-display);font-weight:400;
  letter-spacing:.03em;line-height:1.16;margin:0 0 18px;color:var(--du-cyan)}
.du h1{font-size:clamp(3.2rem,9vw,7.4rem);letter-spacing:.01em;text-transform:none}
.du h2{font-size:clamp(1.8rem,4vw,3.2rem);text-transform:uppercase}
.du h3{font-size:1.35rem}
.du p{margin:0 0 16px}
.du :focus-visible{outline:2px solid var(--du-cyan);outline-offset:3px}
.du-wrap{max-width:var(--du-max);margin:0 auto;padding:0 28px}
.du-sr{position:absolute;width:1px;height:1px;overflow:hidden;clip:rect(0,0,0,0);white-space:nowrap}

/* ── HUD fixo ─────────────────────────────────────────────── */
.du-hud{position:sticky;top:0;z-index:30;background:rgba(14,16,17,.92);
  backdrop-filter:blur(10px);border-bottom:1px solid var(--du-line-soft)}
.du-hud-in{display:flex;align-items:center;gap:22px;min-height:62px;
  max-width:var(--du-max);margin:0 auto;padding:0 28px}
.du-brand{display:inline-flex;align-items:center;gap:10px;white-space:nowrap}
.du-brand-mark{display:grid;place-items:center;width:32px;height:32px;
  border:1px solid var(--du-cyan);color:var(--du-cyan);font-family:var(--du-display);
  font-size:1rem;letter-spacing:.06em}
.du-brand-txt{font-family:var(--du-display);font-size:.92rem;letter-spacing:.14em;
  color:var(--du-ink);line-height:1.15}
.du-brand-txt small{display:block;font-family:var(--du-font);font-size:.56rem;
  letter-spacing:.22em;color:var(--du-muted);text-transform:uppercase}
.du-nav{display:flex;gap:6px;margin-left:auto;flex-wrap:wrap}
.du-nav a{font-size:.68rem;letter-spacing:.16em;text-transform:uppercase;
  color:var(--du-muted);padding:8px 10px}
.du-nav a:hover{color:var(--du-cyan);text-decoration:none}
.du-orbs{display:flex;gap:7px;align-items:center;font-size:.66rem;
  letter-spacing:.14em;color:var(--du-cyan);white-space:nowrap}
.du-orb{width:11px;height:11px;border-radius:50%;border:1px solid var(--du-cyan)}
.du-orb.on{background:var(--du-cyan);box-shadow:0 0 10px var(--du-cyan)}
.du-orb.gold{background:var(--du-gold);border-color:var(--du-gold)}
.du-orb.rose{background:var(--du-rose);border-color:var(--du-rose)}
.du-orb.green{background:var(--du-green);border-color:var(--du-green)}
.du-status{display:flex;justify-content:space-between;gap:16px;
  max-width:var(--du-max);margin:0 auto;padding:10px 28px;
  font-size:.62rem;letter-spacing:.2em;text-transform:uppercase;color:var(--du-muted)}
.du-status b{color:var(--du-cyan);font-weight:400}

/* ── Fases e numeros fantasma ─────────────────────────────── */
.du-phase{position:relative;padding:96px 0;border-bottom:1px solid var(--du-line-soft);
  overflow:hidden;background:radial-gradient(ellipse at 85% 10%,rgba(92,198,208,.09),transparent 55%)}
.du-phase-num{position:absolute;right:4%;top:26px;font-family:var(--du-display);
  font-size:clamp(5rem,13vw,11rem);line-height:1;color:rgba(92,198,208,.09);
  pointer-events:none;user-select:none}
.du-phase-tag{display:flex;align-items:center;gap:14px;margin-bottom:34px;
  font-size:.66rem;letter-spacing:.22em;text-transform:uppercase;color:var(--du-muted)}
.du-phase-tag b{font-family:var(--du-display);font-size:1.1rem;color:var(--du-cyan);font-weight:400}
.du-phase-tag::after{content:"";flex:1;height:1px;background:var(--du-line)}
.du-lead{font-size:1.02rem;color:var(--du-muted);max-width:70ch}
.du-overline{font-size:.68rem;letter-spacing:.2em;text-transform:uppercase;
  color:var(--du-cyan);margin-bottom:12px}

/* ── Cards HUD ────────────────────────────────────────────── */
.du-card{position:relative;background:var(--du-panel);border:1px solid var(--du-line);
  border-radius:var(--du-radius);padding:28px;backdrop-filter:blur(6px)}
.du-card::before,.du-card::after{content:"";position:absolute;width:12px;height:12px;
  border-color:var(--du-cyan);opacity:.7}
.du-card::before{top:-1px;left:-1px;border-top:2px solid;border-left:2px solid}
.du-card::after{bottom:-1px;right:-1px;border-bottom:2px solid;border-right:2px solid}
.du-card-tag{font-size:.62rem;letter-spacing:.2em;text-transform:uppercase;
  color:var(--du-cyan);display:block;margin-bottom:14px}
.du-card h3{text-transform:none;font-size:1.5rem;margin-bottom:12px}
.du-card p{font-size:.9rem;color:var(--du-muted);margin:0}
.du-grid{display:grid;gap:20px}
.du-grid--2{grid-template-columns:repeat(2,1fr)}
.du-grid--3{grid-template-columns:repeat(3,1fr)}
.du-grid--6{grid-template-columns:repeat(3,1fr)}

/* ── Botoes ───────────────────────────────────────────────── */
.du-btn{display:inline-flex;align-items:center;justify-content:center;gap:10px;
  padding:12px 22px;border:1px solid var(--du-cyan);border-radius:var(--du-radius);
  font-size:.72rem;letter-spacing:.18em;text-transform:uppercase;cursor:pointer;
  background:var(--du-cyan);color:#082327;font-weight:700}
.du .du-btn,.du a.du-btn:hover{color:#082327;text-decoration:none}
.du-btn--ghost{background:rgba(50,58,61,.6);color:var(--du-ink);border-color:var(--du-line-soft)}
.du .du-btn--ghost,.du a.du-btn--ghost:hover{color:var(--du-ink)}
.du-btn:hover{filter:brightness(1.12)}

/* ── Hero / cockpit ───────────────────────────────────────── */
.du-hero{position:relative;padding:120px 0 100px;
  background:radial-gradient(circle at 68% 42%,rgba(92,198,208,.16),transparent 46%),
  radial-gradient(circle at 22% 78%,rgba(235,118,126,.09),transparent 40%),var(--du-bg)}
.du-hero-in{display:grid;grid-template-columns:1.1fr .9fr;gap:52px;align-items:center}
.du-hero h1{color:var(--du-ink);margin:0 0 22px}
.du-hero h1 em{font-style:normal;color:var(--du-cyan)}
.du-hero-sub{font-size:1.35rem;color:var(--du-cyan);font-family:var(--du-display);
  letter-spacing:.06em;margin-bottom:14px}
.du-hero-lead{color:var(--du-muted);max-width:48ch;margin-bottom:30px}
.du-hero-actions{display:flex;flex-wrap:wrap;gap:12px;margin-bottom:34px}
.du-controls{border:1px solid var(--du-line);background:var(--du-panel);
  padding:22px;border-radius:var(--du-radius)}
.du-controls h3{font-size:1.05rem;text-transform:uppercase;letter-spacing:.18em;margin-bottom:16px}
.du-control{display:flex;gap:12px;padding:9px 0;border-top:1px solid var(--du-line-soft);
  font-size:.8rem;color:var(--du-muted)}
.du-control b{min-width:64px;color:var(--du-cyan);font-weight:400;letter-spacing:.14em}
.du-socials{display:flex;gap:8px;flex-wrap:wrap;margin-top:22px}
.du-socials a{width:32px;height:32px;display:grid;place-items:center;
  border:1px solid var(--du-line-soft);border-radius:var(--du-radius);font-size:.68rem;
  letter-spacing:.06em;color:var(--du-muted)}
.du-socials a:hover{color:var(--du-cyan);border-color:var(--du-cyan);text-decoration:none}
.du-hint{display:flex;justify-content:space-between;gap:14px;margin-top:56px;
  font-size:.62rem;letter-spacing:.2em;text-transform:uppercase;color:var(--du-muted)}
.du-hint b{color:var(--du-cyan);font-weight:400}

/* ── Perfil (cartao de jogador) ───────────────────────────── */
.du-profile{display:grid;grid-template-columns:1fr 1fr;gap:26px;align-items:start}
.du-profile-row{display:flex;justify-content:space-between;gap:14px;
  padding:11px 0;border-bottom:1px solid var(--du-line-soft);font-size:.84rem}
.du-profile-row span{color:var(--du-muted)}
.du-profile-row b{color:var(--du-cyan);font-weight:400}

/* ── Etapas / niveis ──────────────────────────────────────── */
.du-level{position:relative}
.du-level-no{font-family:var(--du-display);font-size:2.2rem;color:var(--du-cyan);
  opacity:.5;line-height:1;margin-bottom:10px}
.du-level-tag{font-size:.62rem;letter-spacing:.2em;text-transform:uppercase;
  color:var(--du-green);margin-bottom:8px}

/* ── Inventario / listas ──────────────────────────────────── */
.du-list{list-style:none;padding:0;margin:16px 0 0;display:grid;gap:9px}
.du-list li{display:flex;gap:10px;font-size:.86rem;color:var(--du-muted);
  padding:7px 0;border-bottom:1px solid var(--du-line-soft)}
.du-list li b{color:var(--du-cyan);font-weight:400;min-width:26px}
.du-slots{font-size:.62rem;letter-spacing:.18em;text-transform:uppercase;
  color:var(--du-muted);margin-top:10px}

/* ── Catalogo de niveis ───────────────────────────────────── */
.du-level-card figure{margin:0 0 16px;aspect-ratio:16/10;border-radius:var(--du-radius);
  background:linear-gradient(145deg,#182226,#0e1011);border:1px solid var(--du-line-soft);
  display:grid;place-items:center;overflow:hidden}
.du-level-card figure svg{width:78%;height:78%}
.du-level-card h3{font-size:1.25rem}
.du-level-meta{font-size:.62rem;letter-spacing:.18em;text-transform:uppercase;
  color:var(--du-muted);display:block;margin-top:12px}

/* ── Depoimento ───────────────────────────────────────────── */
.du-quote{max-width:800px;margin:0 auto;text-align:center;padding:34px}
.du-quote p{font-family:var(--du-display);font-size:1.5rem;color:var(--du-ink);
  line-height:1.5;margin-bottom:20px}
.du-quote-by{font-size:.72rem;letter-spacing:.18em;text-transform:uppercase;color:var(--du-cyan)}
.du-social-grid{display:grid;grid-template-columns:repeat(6,1fr);gap:14px;margin-top:34px}
.du-social-grid div{aspect-ratio:1;border:1px solid var(--du-line-soft);border-radius:50%;
  display:grid;place-items:center;overflow:hidden;background:#182226}
.du-social-grid svg{width:70%;height:70%}

/* ── Formulario ───────────────────────────────────────────── */
.du-form{display:grid;gap:14px}
.du-form label{font-size:.66rem;letter-spacing:.18em;text-transform:uppercase;color:var(--du-muted)}
.du-form input,.du-form textarea{width:100%;background:rgba(14,16,17,.8);
  border:1px solid var(--du-line-soft);border-radius:var(--du-radius);padding:12px 14px;
  color:var(--du-ink);font-family:var(--du-font);font-size:.9rem}
.du-form textarea{min-height:120px;resize:vertical}
.du-form .du-btn{justify-self:start;margin-top:8px}

/* ── Rodape ───────────────────────────────────────────────── */
.du-footer{position:relative;padding:70px 0 30px;background:var(--du-bg-2);
  border-top:1px solid var(--du-line-soft);overflow:hidden}
.du-footer-ghost{font-family:var(--du-display);font-size:clamp(2.4rem,8vw,6rem);
  color:rgba(92,198,208,.10);text-align:center;letter-spacing:.06em;white-space:nowrap;
  margin-bottom:34px;user-select:none}
.du-footer-grid{display:grid;grid-template-columns:2fr 1fr 1fr;gap:34px}
.du-footer-grid h4{font-size:.72rem;letter-spacing:.2em;text-transform:uppercase;
  color:var(--du-cyan);margin-bottom:14px}
.du-footer-grid a{display:block;font-size:.82rem;color:var(--du-muted);padding:4px 0}
.du-footer-bottom{display:flex;justify-content:space-between;gap:16px;flex-wrap:wrap;
  margin-top:44px;padding-top:18px;border-top:1px solid var(--du-line-soft);
  font-size:.66rem;letter-spacing:.14em;text-transform:uppercase;color:var(--du-muted)}

/* ── Slot ThreeJS declarativo ─────────────────────────────── */
.theme-scene{position:relative;width:100%;overflow:hidden;
  border:1px solid var(--du-line);border-radius:var(--du-radius-lg);
  background:radial-gradient(circle at 24% 22%,rgba(92,198,208,.18),transparent 58%),
  radial-gradient(circle at 78% 72%,rgba(235,118,126,.12),transparent 60%),var(--du-bg-2);
  isolation:isolate}
.theme-scene[data-scene]{min-height:200px}
.theme-scene.theme-scene--hero{min-height:320px;margin:0 0 34px}
.theme-scene.theme-scene--home_top{min-height:230px;margin:0 0 26px}
.theme-scene.theme-scene--footer_top{min-height:170px;margin:0 0 18px}
.theme-scene__fallback{position:absolute;inset:0;
  background-image:radial-gradient(circle,rgba(92,198,208,.72) 1.4px,transparent 2px),
  radial-gradient(circle,rgba(223,223,223,.30) 1px,transparent 1.5px),
  radial-gradient(circle,rgba(255,223,0,.26) 2px,transparent 3px);
  background-size:28px 28px,47px 47px,103px 103px;
  background-position:0 0,17px 23px,51px 37px;opacity:.86}
.theme-scene__fallback::after{content:"";position:absolute;left:50%;top:50%;
  width:280px;height:280px;margin:-140px 0 0 -140px;border-radius:50%;
  border:1px solid rgba(92,198,208,.34);
  box-shadow:0 0 0 42px rgba(92,198,208,.05),0 0 0 88px rgba(92,198,208,.04)}
.theme-scene[data-scene="portfolio-3d"] .theme-scene__fallback{
  background-image:linear-gradient(135deg,transparent 46%,rgba(92,198,208,.28) 47%,
  rgba(92,198,208,.28) 53%,transparent 54%);background-size:64px 64px}
.theme-scene[data-scene="tools-3d"] .theme-scene__fallback{
  background-image:repeating-linear-gradient(60deg,transparent 0 22px,
  rgba(235,118,126,.26) 23px 25px,transparent 26px 48px)}
.theme-scene[data-scene="not-found"] .theme-scene__fallback{opacity:.30}
.du-scene-caption{display:flex;align-items:center;gap:12px;flex-wrap:wrap;
  padding:12px 0 24px;font-size:.66rem;letter-spacing:.18em;text-transform:uppercase;color:var(--du-muted)}
.du-scene-caption b{color:var(--du-cyan);font-weight:400}
.du-scene-caption::after{content:"";flex:1;height:1px;background:var(--du-line)}
.du-scene-lite .theme-scene__fallback{opacity:.36}
.du-scene-lite .theme-scene.theme-scene--hero{min-height:210px}

/* ── 404 ──────────────────────────────────────────────────── */
.du-404{text-align:center;padding:70px 0}
.du-404 strong{display:block;font-family:var(--du-display);font-size:clamp(5rem,16vw,11rem);
  color:var(--du-cyan);line-height:1;margin-bottom:16px}

@media(max-width:900px){
 .du-hero-in,.du-profile{grid-template-columns:1fr}
 .du-grid--3,.du-grid--6,.du-footer-grid{grid-template-columns:repeat(2,1fr)}
 .du-nav{display:none}
}
@media(max-width:620px){
 .du-grid--2,.du-grid--3,.du-grid--6,.du-footer-grid{grid-template-columns:1fr}
 .du-social-grid{grid-template-columns:repeat(3,1fr)}
 .du-phase{padding:64px 0}
 .du-hero{padding:76px 0 64px}
 .theme-scene.theme-scene--hero{min-height:210px}
 .du-hud-in{padding:0 16px;gap:10px}
 .du-brand-txt{font-size:.72rem;letter-spacing:.08em}
 .du-brand-txt small{font-size:.5rem;letter-spacing:.12em}
 .du-brand-mark{width:28px;height:28px;font-size:.85rem}
 nav.du-orbs{display:none}
 .du-orbs{gap:4px;font-size:.56rem;letter-spacing:.06em}
 .du-orbs .du-orb{width:8px;height:8px}
 .du-orb:nth-of-type(n+4){display:none}
 .du-status{padding:8px 16px;font-size:.55rem;letter-spacing:.1em}
 .du-wrap{padding:0 16px}
}
@media(prefers-reduced-motion:reduce){.theme-scene__fallback{opacity:.22}}

</style>
<div class="du du-hud"><div class="du-hud-in">
  <a class="du-brand" href="{{ home|default('/') }}" aria-label="{{ text_brand|default('David L. Almeida') }}"><span class="du-brand-mark">DA</span><span class="du-brand-txt">DAVID L. ALMEIDA<small>Creative Developer</small></span></a>
  <nav class="du-nav" aria-label="Navegação principal">
    <a href="#fase-01">SOBRE</a>
    <a href="#fase-02">PROCESSO</a>
    <a href="#fase-04">HABILIDADES</a>
    <a href="#fase-05">SERVIÇOS</a>
    <a href="#fase-06">CATÁLOGO</a>
    <a href="#fase-08">CONTATO</a>
  </nav>
  <div class="du-orbs" aria-label="Orbes coletados">ORBES 00/10<span class="du-orb on"></span><span class="du-orb on"></span><span class="du-orb gold"></span><span class="du-orb rose"></span><span class="du-orb green"></span></div>
  <nav class="du-orbs" aria-label="{{ text_languages|default('Idiomas') }}">{% for lang in languages|default([]) %}<a href="{{ lang.href }}" hreflang="{{ lang.code }}">{{ lang.code }}</a>{% endfor %}</nav>
</div>
<div class="du-status"><span>FASE 00 — DECOLAGEM</span><span>DISTÂNCIA <b>0 KM</b></span></div>
</div>

